 1→import type { ActionFunctionArgs } from "react-router";
 2→import { authenticate } from "../shopify.server";
 3→import db from "../db.server";
 4→
 5→export const action = async ({ request }: ActionFunctionArgs) => {
 6→  const { shop, session } = await authenticate.webhook(request);
 7→
 8→  // Webhook requests can trigger multiple times and after an app has already been uninstalled.
 9→  // Delete all shop data immediately on uninstall (Shopify App Store requirement).
10→  // The shop/redact GDPR webhook fires 48 hours later and also runs this cleanup.
11→  if (session) {
12→    await Promise.all([
13→      db.session.deleteMany({ where: { shop } }),
14→      db.zipCode.deleteMany({ where: { shop } }),
15→      db.deliveryRule.deleteMany({ where: { shop } }),
16→      db.waitlistEntry.deleteMany({ where: { shop } }),
17→      db.widgetConfig.deleteMany({ where: { shop } }),
18→      db.subscription.deleteMany({ where: { shop } }),
19→      db.shopSettings.deleteMany({ where: { shop } }),
20→    ]);
21→  }
22→
23→  return new Response();
24→};
