 1→import type { ActionFunctionArgs } from "react-router";
 2→import { authenticate } from "../shopify.server";
 3→import { syncSubscriptionFromShopify } from "../billing.server";
 4→
 5→export const action = async ({ request }: ActionFunctionArgs) => {
 6→  const { shop, payload } = await authenticate.webhook(request);
 7→
 8→  try {
 9→    type SubscriptionPayload = {
10→      app_subscription?: {
11→        admin_graphql_api_id?: string;
12→        name?: string;
13→        status?: string;
14→      };
15→    };
16→
17→    const data = payload as SubscriptionPayload;
18→    const sub = data?.app_subscription;
19→
20→    if (sub) {
21→      await syncSubscriptionFromShopify(shop, [
22→        {
23→          id: sub.admin_graphql_api_id ?? "",
24→          name: sub.name ?? "",
25→          status: sub.status ?? "",
26→        },
27→      ]);
28→    }
29→  } catch {
30→    // Subscription sync failed — will be retried on next billing check
31→  }
32→
33→  return new Response();
34→};
