 1→/**
 2→ * GDPR: customers/redact
 3→ *
 4→ * Shopify sends this when a customer requests deletion of their data,
 5→ * or when 10 days have passed after a shop uninstalls the app.
 6→ *
 7→ * You must delete all personally identifiable information for this customer.
 8→ *
 9→ * Required for Shopify App Store listing.
10→ * https://shopify.dev/docs/apps/build/privacy-law-compliance
11→ */
12→import type { ActionFunctionArgs } from "react-router";
13→import { authenticate } from "../shopify.server";
14→import db from "../db.server";
15→
16→export const action = async ({ request }: ActionFunctionArgs) => {
17→  const { shop, payload } = await authenticate.webhook(request);
18→
19→  const customerEmail = payload?.customer?.email;
20→
21→  if (customerEmail) {
22→    // Delete all PII for this customer: waitlist entries contain email addresses
23→    await db.waitlistEntry.deleteMany({
24→      where: { shop, email: customerEmail },
25→    });
26→  }
27→
28→  return new Response();
29→};
