46→          <Layout.Section>
47→            <Card>
48→              <SkeletonBodyText lines={4} />
49→            </Card>
50→          </Layout.Section>
51→        </Layout>
52→      </SkeletonPage>
53→    );
54→  }
55→
56→  return <Outlet />;
57→}
